import React, { useState } from 'react';
import { useLocation } from 'react-router-dom';
import { FiMenu, FiX } from 'react-icons/fi'; // Importing icons from react-icons

const Header = ({ className }) => {
  const [menuOpen, setMenuOpen] = useState(false);
  const location = useLocation();
  const isMainPage = location.pathname === '/';

  const scrollToSection = (id) => {
    const element = document.getElementById(id);
    if (element) {
      window.scrollTo({
        top: element.offsetTop,
        behavior: 'smooth'
      });
    }
  };

  return (
    <header
      className={`fixed top-0 left-0 w-full text-white p-4 z-50 transition-all duration-500 ${className}`}
      aria-label="Main Navigation"
    >
      <nav className="container mx-auto flex justify-between items-center">
        <div className="text-2xl font-bold">
          <img
            src="./images/doad_logo_fulltext_white.png"
            className="max-h-10 ml-7"
            alt="Doad Logo"
          />
        </div>

        {/* Hamburger Menu Icon */}
        <div className="md:hidden">
          <button
            onClick={() => setMenuOpen(!menuOpen)}
            aria-label="Toggle Navigation Menu"
          >
            {menuOpen ? <FiX size={24} /> : <FiMenu size={24} />}
          </button>
        </div>

        {/* Navigation Links */}
        <ul
          className={`md:flex md:space-x-4 md:items-center md:static absolute top-16 left-0 w-full bg-gray-800 p-4 md:bg-transparent md:p-0 transition-transform duration-300 ease-in-out ${
            menuOpen ? 'transform translate-y-0' : 'transform -translate-y-full'
          }`}
        >
          {isMainPage ? (
            <>
              <li>
                <a
                  href="#work"
                  className="hover:underline"
                  aria-label="Navigate to Work section"
                  onClick={(e) => {
                    e.preventDefault();
                    scrollToSection('work');
                    setMenuOpen(false); // Close menu on selection
                  }}
                >
                  WORK
                </a>
              </li>
              <li>
                <a
                  href="#expertise"
                  className="hover:underline"
                  aria-label="Navigate to Expertise section"
                  onClick={(e) => {
                    e.preventDefault();
                    scrollToSection('expertise');
                    setMenuOpen(false); // Close menu on selection
                  }}
                >
                  EXPERTISE
                </a>
              </li>
              <li>
                <a
                  href="#about"
                  className="hover:underline"
                  aria-label="Navigate to About section"
                  onClick={(e) => {
                    e.preventDefault();
                    scrollToSection('about');
                    setMenuOpen(false); // Close menu on selection
                  }}
                >
                  ABOUT
                </a>
              </li>
              <li>
                <a
                  href="#contact"
                  className="hover:underline"
                  aria-label="Navigate to Contact section"
                  onClick={(e) => {
                    e.preventDefault();
                    scrollToSection('contact');
                    setMenuOpen(false); // Close menu on selection
                  }}
                >
                  CONTACT
                </a>
              </li>
            </>
          ) : (
            <>
              <li>
                <a
                  href="/#work"
                  className="hover:underline"
                  aria-label="Navigate to Work section on landing page"
                  onClick={() => setMenuOpen(false)} // Close menu on selection
                >
                  WORK
                </a>
              </li>
              <li>
                <a
                  href="/#expertise"
                  className="hover:underline"
                  aria-label="Navigate to Expertise section on landing page"
                  onClick={() => setMenuOpen(false)} // Close menu on selection
                >
                  EXPERTISE
                </a>
              </li>
              <li>
                <a
                  href="/#about"
                  className="hover:underline"
                  aria-label="Navigate to About section on landing page"
                  onClick={() => setMenuOpen(false)} // Close menu on selection
                >
                  ABOUT
                </a>
              </li>
              <li>
                <a
                  href="/#contact"
                  className="hover:underline"
                  aria-label="Navigate to Contact section on landing page"
                  onClick={() => setMenuOpen(false)} // Close menu on selection
                >
                  CONTACT
                </a>
              </li>
            </>
          )}
        </ul>
      </nav>
    </header>
  );
};

export default Header;
